# 4급 CH6 조동사 (51~60) 2차 감수
X(4, 51, r="능력을 나타내는 can(~할 수 있다)은 be able to로 바꿔 쓸 수 있다. be동사는 주어에 맞춘다.",
  n=["can(~할 수 있다)과 같은 뜻의 be able to이므로", "may는 ‘~일지도 모른다, ~해도 된다’라 뜻이 다르므로", "must는 ‘~해야 한다’라 뜻이 다르므로", "has to는 ‘~해야 한다’라 뜻이 다르므로", "might는 ‘~일지도 모른다’라 뜻이 다르므로"],
  st="① 밑줄 친 can의 뜻을 확인한다: ‘~할 수 있다’(능력). → ② 같은 뜻의 표현은 be able to + 동사원형이다. be동사는 주어({0})에 맞춘다. → ③ 정답은 {n}.",
  R="She이므로 is", B="They이므로 are", C="Jane이므로 is", D="Tom이므로 is", E="I이므로 am", F="We이므로 are")

X(4, 52, r="must는 ‘반드시 ~해야 한다’(의무), can은 ‘~할 수 있다’, may·might는 ‘~일지도 모른다’, will은 ‘~할 것이다’이다.",
  n=["can은 ‘~할 수 있다’라 뜻이 맞지 않으므로", "may는 ‘~해도 된다, ~일지도 모른다’라 뜻이 맞지 않으므로", "‘반드시 나가야 한다’는 의무를 나타내는 must가 알맞으므로", "might는 ‘~일지도 모른다’라 뜻이 맞지 않으므로", "will은 ‘~할 것이다’라 의무의 뜻이 없으므로"],
  st="① 우리말에서 조동사에 해당하는 말을 찾는다: {0}. → ② {1} → ③ 정답은 {a}.",
  R=("‘반드시 나가야 한다’", "의무를 나타내는 조동사는 must다."), B=("‘입어야 한다’", "발문이 have to의 형태를 물었다. 주어 Jane이 3인칭 단수이므로 has to다."), C=("‘나가야 한다’", "의무를 나타내는 조동사는 must다."),
  D=("‘청소해야 한다’", "발문이 have to의 형태를 물었다. 주어 Tom이 3인칭 단수이므로 has to다."), E=("‘출발해야 한다’", "발문이 have to의 형태를 물었다. 주어 We가 복수이므로 have to다."),
  F=("‘해야 한다’", "발문이 have to의 형태를 물었다. 주어 Students가 복수이므로 have to다."))

X(4, 53, r="must not은 ‘~해서는 안 된다’(금지), don't have to는 ‘~할 필요가 없다’(불필요)로 뜻이 다르다.",
  n=["may는 허락을 구할 때 쓰는 것이 맞으므로", "must(틀림없다)가 may(일지도 모른다)보다 강한 확신인 것이 맞으므로", "can의 부정형이 cannot인 것이 맞으므로", "must not은 금지, don't have to는 불필요로 뜻이 다르므로", "능력의 can은 be able to로 바꿔 쓸 수 있으므로"],
  st="① 설명마다 해당 조동사의 뜻과 형태를 떠올려 맞는지 본다. → ② {0} → ③ 정답은 {n}.",
  R="④가 틀렸다. must not은 ‘~하면 안 된다’, don't have to는 ‘~할 필요가 없다’로 뜻이 다르다.", B="①이 틀렸다. might는 확실한 미래가 아니라 가능성이 낮은 추측을 나타낸다.", C="①이 틀렸다. must not은 금지, don't have to는 불필요다.",
  D="④가 틀렸다. 조동사 can 뒤에는 -s를 붙이지 않은 동사원형이 온다.", E="②가 틀렸다. must 뒤에는 to 없이 동사원형이 온다.", F="⑤가 틀렸다. be able to의 be동사는 주어에 따라 am/are/is로 변한다.")
RV(4, 53, "F", fx=True, why="수정 예시의 틀린 설명(don't have to는 금지를 나타낸다)이 원문항의 정답(must not과 don't have to는 같은 의미)과 같은 내용이어서, 다른 내용(be able to 뒤에 -ing형을 쓴다)으로 바꿨다.")

X(4, 54, r="조동사(can, must, might, may, will, should)와 have to 뒤에는 동사원형을 쓴다.",
  n=["must 뒤에 동사원형 be를 써서 옳으므로", "have to 뒤에 동사원형 finish를 써서 옳으므로", "can 뒤에는 sings가 아니라 동사원형 sing을 써야 하므로", "might 뒤에 동사원형 go를 써서 옳으므로", "May I 뒤에 동사원형 use를 써서 옳으므로"],
  st="① 밑줄 친 동사 바로 앞의 조동사를 찾는다. → ② 조동사 뒤는 주어가 무엇이든 동사원형이다. -s, -ing, to, 과거형이 붙은 것을 찾는다. → ③ {0} 정답은 {n}.",
  R="③은 can 뒤에 sings를 썼다. sing으로 고친다.", B="②는 can 뒤에 playing을 썼다. play로 고친다.", C="①은 can 뒤에 sings를 썼다. sing으로 고친다.", D="③은 can 뒤에 reads를 썼다. read로 고친다.", E="⑤는 can 뒤에 to help를 썼다. to를 뺀다.",
  F="①은 can 뒤에 are를 썼다. be로 고친다.")

X(4, 55, r="조동사에는 -s를 붙이지 않고, 조동사 뒤에는 동사원형을 쓴다. 부정은 조동사 + not + 동사원형이다.",
  pre=["문장별 판정: ⓐ X. can 뒤에는 동사원형 ride. ⓑ O. might not + 동사원형. ⓒ O. Can + 주어 + 동사원형 의문문. ⓓ X. 조동사 may에는 -s를 붙이지 않는다. ⓔ X. May I 뒤에는 동사원형 speak."],
  k="옳은 문장은 ⓑ, ⓒ 두 개다.", n=["옳은 문장은 ⓑ, ⓒ 두 개이므로"] * 5,
  st="① 밑줄마다 두 가지를 본다: 조동사에 -s가 붙지 않았는지, 조동사 뒤가 동사원형인지. → ② {0} → ③ 옳은 문장은 {a}이다.",
  R="ⓐ can rides(ride), ⓓ mays(may), ⓔ speaking(speak)이 틀렸다. ⓑ, ⓒ만 옳다.", B="a can goes(go), e can reads(read)가 틀렸다. b, c, d는 옳다.", C="a can rides(ride), d must to go(must go)가 틀렸다. b, c, e는 옳다.",
  D="e can helps(help)만 틀렸다.", E="틀린 문장이 없다. 다섯 문장 모두 조동사 + 동사원형이다.", F="c must wears(wear), d can to help(can help)가 틀렸다. a, b, e는 옳다.")
RV(4, 55, "E", fx=True, why="수정 예시의 정답이 원문항과 같은 2개(②)여서, ⓓ·ⓔ를 옳은 문장으로 되돌려 4개로 했다(틀린 문장은 ⓑ 하나).")

X(4, 56, r="have to(~해야 한다)는 주어가 3인칭 단수이면 has to, 그 밖에는 have to를 쓴다. 뒤에는 동사원형이 온다.",
  n=["주어 He는 3인칭 단수라 have to가 아니라 has to를 쓰므로", "to가 빠져 has clean이 되어 틀리므로", "3인칭 단수 주어 He에 has to + 동사원형이 알맞으므로", "having to만으로는 동사 자리를 채울 수 없으므로", "be동사와 have to를 함께 쓸 수 없으므로"],
  st="① 빈칸 뒤가 동사원형({0})이다. ‘~해야 한다’는 have to + 동사원형이 들어간다. → ② 주어({1})에 맞춘다. → ③ 정답은 {a}.",
  R=("clean", "He는 3인칭 단수이므로 has to"), B=("study", "We는 복수이므로 have to"), C=("clean", "He는 3인칭 단수이므로 has to"), D=("leave", "They는 복수이므로 have to"), E=("finish", "I이므로 have to"), F=("wear", "Jane은 3인칭 단수이므로 has to"))

X(4, 57, r="must에는 ‘~해야 한다’(의무)와 ‘~임에 틀림없다’(강한 추측)의 두 뜻이 있다. 근거가 있고 뒤에 be나 상태를 나타내는 말이 오면 추측이다.",
  n=["‘숙제를 끝내야 한다’는 의무이므로", "불이 켜져 있다는 근거로 ‘집에 있는 것이 틀림없다’고 추측하므로", "‘안전띠를 매야 한다’는 의무이므로", "‘먹으면 안 된다’는 금지이므로", "‘은행에 가야 한다’는 의무이므로"],
  st="① 제시문의 must를 풀어 본다: {0}. 근거를 보고 하는 강한 추측이다. → ② 보기마다 ‘~해야 한다’(의무)인지 ‘~임에 틀림없다’(추측)인지 가른다. → ③ {1} 정답은 {n}.",
  R=("하루 종일 연습했으니 ‘피곤한 것이 틀림없다’", "②만 불이 켜져 있다는 근거로 추측한다."), B=("땅이 젖었으니 ‘비가 온 것이 틀림없다’", "⑤만 얼굴이 창백하다는 근거로 추측한다."), C=("하루 종일 연습했으니 ‘피곤한 것이 틀림없다’", "⑤만 불이 켜져 있다는 근거로 추측한다."),
  D=("밤새 공부했으니 ‘졸린 것이 틀림없다’", "①만 전화를 받지 않는다는 근거로 추측한다."), E=("문이 열려 있으니 ‘누군가 안에 있는 것이 틀림없다’", "②만 차가 있다는 근거로 추측한다."), F=("경주에서 이겼으니 ‘기쁜 것이 틀림없다’", "⑤만 웃고 있다는 근거로 추측한다."))

X(4, 58, r="Must + 주어 ~?는 Do/Does + 주어 + have to ~?로 바꿔 쓸 수 있다. Do/Does 뒤이므로 have는 원형으로 쓴다.",
  n=["주어 he는 3인칭 단수라 Do가 아니라 Does를 쓰므로", "Does 뒤에는 has가 아니라 동사원형 have를 쓰므로", "3인칭 단수 주어 he에 Does, 뒤에 동사원형 have가 알맞으므로", "have to는 일반동사처럼 Do/Does로 묻고 be동사로 묻지 않으므로", "Has ~ do to라고는 쓰지 않으므로"],
  st="① must와 같은 뜻은 have to다. have to의 의문문은 일반동사처럼 Do/Does로 만든다. → ② 주어를 본다: {0}. → ③ Do/Does 뒤이므로 둘째 빈칸은 동사원형 have다. 정답은 {a}.",
  R="he는 3인칭 단수이므로 Does", B="Tom은 3인칭 단수이므로 Does", C="he는 3인칭 단수이므로 Does", D="they는 복수이므로 Do", E="Jane은 3인칭 단수이므로 Does", F="we는 복수이므로 Do")

X(4, 59, r="‘~할 수 없었다’는 can의 과거 부정 could not + 동사원형으로 쓴다.",
  n=["yesterday가 있어 현재형 can not을 쓸 수 없으므로", "could not 뒤에 과거형 went를 쓸 수 없으므로", "did not go는 ‘가지 않았다’라 ‘갈 수 없었다’는 뜻이 빠지므로", "could not 뒤에 goes를 쓸 수 없으므로", "could not + 동사원형 go로 ‘갈 수 없었다’를 바르게 옮겼으므로"],
  st="① 우리말 ‘{0}’는 과거의 일이다. can의 과거형 could를 쓰고 부정이므로 could not이다. → ② 조동사 뒤는 과거의 일이어도 동사원형이다: {1}. → ③ 정답은 {n}.",
  R=("갈 수 없었다", "go"), B=("끝낼 수 없었다", "finish"), C=("수영할 수 없었다", "swim"), D=("도울 수 없었다", "help"), E=("탈 수 없었다", "take"), F=("읽을 수 없었다", "read"))

X(4, 60, r="might는 가능성은 있지만 확실하지 않은 일을 추측할 때 쓴다(~일지도 모른다). will은 그렇게 될 것이라고 확실하게 말할 때 쓴다.",
  n=["100% 확실하면 will을 쓰므로", "might에는 명령의 뜻이 없으므로", "이 문장은 과거의 경험이 아니라 오늘 일을 짐작하는 말이므로", "주어에 따라 will을 might로 바꾸는 규칙은 없으므로", "늦게 일어났으니 늦을 수도 있다는 확실하지 않은 추측이므로"],
  st="① 상황을 읽는다: {0}. → ② 그 일이 꼭 일어난다고 할 수 없으므로 will(확실한 예측)이 아니라 might(~일지도 모른다)를 썼다. → ③ ‘가능성은 있지만 확실하지 않은 추측’이라고 말한 것은 {n}.",
  R="평소보다 한 시간 늦게 일어났지만 지각할지는 아직 모른다", B="전화를 받지 않았지만 바쁜지는 확실하지 않다", C="평소보다 한 시간 늦게 일어났지만 지각할지는 아직 모른다", D="먹구름이 몰려오지만 비가 올지는 확실하지 않다",
  E="집에 없지만 학교에 있는지는 확실하지 않다", F="버스가 느리지만 늦을지는 아직 모른다")
RV(4, 60, "B", v="수정(내용)", why="정답 확인. 다만 정답만 문장 내용(바쁠 가능성)을 말하고 오답 네 개는 문장과 관계없는 일반론(‘강한 의무’, ‘허락’, ‘100% 확실한 미래’, ‘과거의 습관’)이라 정답이 눈에 띈다. 원문항의 오답은 모두 그 상황에 맞춘 그럴듯한 설명이다. [상황]/[문장] 구분과 밑줄이 사라진 점도 다르다.", fix="오답을 상황에 맞춘 오개념으로, 원문항 형식으로")
